type Want = { thing: string; n?: number; min?: number; max?: number };
const n = (thing: string, count: number): Want => ({ thing, n: count });
const r = (thing: string, min: number, max: number): Want => ({ thing, min, max });

type MakeOpts = { method?: string; vessel?: string; forbid?: string[]; dislike?: string[]; allow?: string[]; order?: string[]; out?: string[]; features?: AuthoredTask['features']; grammar?: string[]; phrases?: string[] };
/** a make task */
const mk = (id: string, rank: number, person: string, say: string, want: Want[], o: MakeOpts = {}): AuthoredTask =>
  ({ id, rank, arch: 'make', person, say, want, ...o }) as AuthoredTask;

/** a sorting task; items are [label, bin, thing?] */
const so = (id: string, rank: number, say: string, bins: string[], items: [string, string, string?][], o: { grammar?: string[]; phrases?: string[]; person?: string } = {}): AuthoredTask =>
  ({
    id,
    rank,
    arch: 'sort',
    say,
    bins,
    items: items.map(([text, bin, thing], i) => ({ id: String.fromCharCode(97 + i), text, bin, ...(thing ? { thing } : {}) })),
    ...o,
  }) as AuthoredTask;

/** sort template patterns: [label, bin] */
const pat = (rows: [string, string][]) => rows.map(([text, bin]) => ({ text, bins: [bin] }));

